import java.util.*;

public class Main {
    public static void main(String[] args) {
        long[] input = parseInput();
        long x = input[0];
        long y = input[1];

        long abs_x = Math.abs(x);
        long abs_y = Math.abs(y);
        long a = abs_x + abs_y;

        if (abs_x == x && abs_y == y) {
            print(0, a, a, 0);
        } else if (abs_x != x && abs_y != y) {
            print(-a, 0, 0, -a);
        } else if (abs_x != x) {
            print(-a, 0, 0, a);
        } else {
            print(0, -a, a, 0);
        }
    }

    private static long[] parseInput() {
        Scanner scanner = new Scanner(System.in);
        long x = scanner.nextLong();
        long y = scanner.nextLong();
        return new long[]{x, y};
    }

    private static void print(long a, long b, long c, long d) {
        System.out.println(a + " " + b + " " + c + " " + d);
    }
}

